const CACHE_NAME = "location-voiture-cache-v1";
const OFFLINE_URL = "/_not-found";

// Install event: cache static assets
self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll([
        "/",
        "/manifest.json",
        OFFLINE_URL,
        // In a real app, we'd cache JS/CSS chunks generated by Next.js
      ]);
    })
  );
  self.skipWaiting();
});

// Activate event: clean up old caches
self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames
          .filter((name) => name !== CACHE_NAME)
          .map((name) => caches.delete(name))
      );
    })
  );
  self.clients.claim();
});

// Fetch event: Network-first, fallback to cache for navigation
self.addEventListener("fetch", (event) => {
  // Only handle GET requests
  if (event.request.method !== "GET") return;

  event.respondWith(
    fetch(event.request)
      .then((response) => {
        // Cache successful responses for future offline use
        if (response.status === 200) {
          const responseClone = response.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseClone);
          });
        }
        return response;
      })
      .catch(async () => {
        // On network failure, try cache
        const cachedResponse = await caches.match(event.request);
        if (cachedResponse) {
          return cachedResponse;
        }

        // If navigation request and not in cache, show offline page
        if (event.request.mode === "navigate") {
          return caches.match(OFFLINE_URL);
        }

        return new Response("Network error happened", {
          status: 408,
          headers: { "Content-Type": "text/plain" },
        });
      })
  );
});

// Background Sync event
self.addEventListener("sync", (event) => {
  if (event.tag === "location-voiture-sync") {
    console.log("Background sync triggered!");
    event.waitUntil(processSyncQueue());
  }
});

// Process the IndexedDB sync queue
async function processSyncQueue() {
  // In a real implementation, this would:
  // 1. Open the Dexie database
  // 2. Fetch all pending syncs from `syncQueue` table
  // 3. For each pending sync:
  //    a. Attempt HTTP POST/PATCH to Supabase via fetch()
  //    b. If success, remove from queue
  //    c. If failed (5xx), increment retry count
  //    d. If failed (4xx), mark as failed for manual intervention
  
  // Note: Due to limitations of accessing Next.js Server Actions from SW,
  // we would hit standard API routes (/api/sync/inspections) for this.
  
  try {
    const response = await fetch("/api/health");
    if (response.ok) {
      // API is reachable, we can trigger client-side sync via postMessage
      const clients = await self.clients.matchAll();
      clients.forEach(client => {
        client.postMessage({ type: 'SYNC_NOW' });
      });
    }
  } catch (error) {
    console.error("Sync failed:", error);
    throw error; // Re-throw to tell the browser to retry the sync later
  }
}
